{
  "url": "https://ccmc.gsfc.nasa.gov/RoR_WWW/SH/ENLIL/2017/Lan_Jian_112717_SH_1/Lan_Jian_112717_SH_1_control_file.txt",
  "prompt": "Return verbatim the full contents of this control file, especially lines with ambient (a6b1), runpar (g53q5), vfast, vslow, vrfast, vrslow, dfast, tfast, bfast, bscl, xalpha, gamma, qheat, cone parameters."
}

{
  "url": "https://ccmc.gsfc.nasa.gov/ror/api/run_metadata.php?runnumber=Lan_Jian_112717_SH_1",
  "prompt": "Return verbatim all fields relating to ambient wind parameters, runpar, gamma, heating, cone parameters, inner boundary, and any descriptive text for these fields."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1504.04402",
  "prompt": "Quote verbatim the description of ENLIL inner boundary conditions and ambient settings: ambient code (a3b2? a6b1?), vfast/vslow, velocity reductions, density and temperature of the fast wind at 21.5 Rs, rules for density (momentum flux) and temperature (thermal pressure balance), Br scaling, alpha fraction; cone CME density/temperature (d4t1x1 meaning: CME density 4x fast-wind density, temperature equal to fast wind), version numbers (ENLIL 2.7/2.8, WSA 2.2), gamma. Title, authors, journal, volume, page."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1801.07818",
  "prompt": "Quote verbatim all statements about ENLIL inner boundary/ambient settings (a4b1 etc.), density and temperature rules (momentum flux / thermal pressure balance), fast wind density/temperature values, velocity reduction, Br, cone model defaults (density 4x, temperature), ENLIL/WSA versions, and the paper's title, authors, journal, volume, article number."
}

{
  "query": "ENLIL inner boundary density \"momentum flux\" temperature \"thermal pressure\" balance fast wind 0.1 AU WSA \"fast stream\" Odstrcil Br scaled",
  "mode": "extended"
}

{
  "url": "https://iopscience.iop.org/article/10.3847/1538-4365/ab77cb",
  "prompt": "Quote verbatim the ENLIL inner boundary prescriptions: velocity from WSA (and reductions), density (momentum flux), temperature (thermal pressure), Br (scaling, bfast, bscl), fast-stream values (vfast, dfast, tfast), alpha fraction, gamma, heating; also cone CME defaults. Title, authors, journal, volume, article number."
}

{
  "query": "ccmc.gsfc.nasa.gov viewrun ENLIL \"a6b1\" 2024 OR 2025 WSA 5 \"tfast\"",
  "mode": "standard"
}

{
  "url": "https://arxiv.org/html/2512.14462",
  "prompt": "Quote verbatim all passages about ENLIL ambient parameters: vfast, vslow, vrfast, vrslow, dfast, tfast, bfast, bscl, xalpha, the a-settings (a6b1, a8b1, etc.), how versions differ in scaling/clipping WSA values, density/temperature rules, g53q5 or gamma/heating, cone defaults (d4t1x1, cloud density ratio, temperature), WSA versions (5.4, 2.2), ENLIL versions (2.9e, 2.8f). Title, authors, date."
}

{
  "url": "https://arxiv.org/html/2512.14462",
  "offset": 100000,
  "prompt": "Quote verbatim any WSA velocity equation and coefficients (WSA 2.2 vs 4.5 vs 5.x), vrfast/vrslow values in Table 3, qheat/heating codes (g53q5?), cone cloud defaults, a6b1/a8b1 definitions."
}

{
  "url": "https://arxiv.org/html/2512.14462",
  "prompt": "Quote verbatim: (1) Table 3 completely, every row with both columns (a3b2, a8b1), including vrfast, vrslow, vmean, nbrad, heat/qheat/nheat, gamma; (2) any sentence about WSA velocity equation coefficients for versions 2.2 and 4.5 (or ADAPT-WSA 5.x), and NOAA operational WSA-Enlil v3.0 (WSA 5.4 + Enlil 2.9e) settings; (3) cone parameters used (cloud density ratio, temperature, radcav)."
}

{
  "query": "\"285 + 625\" WSA solar wind speed expansion factor \"2/9\" coronal hole boundary",
  "mode": "standard"
}

{
  "url": "https://ccmc.gsfc.nasa.gov/RoR_WWW/SWREDI/2017/arge_WSA_ADAPT_v1.pdf",
  "prompt": "Quote any WSA velocity equation with coefficients, radius, version number."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1303.0563",
  "prompt": "Quote verbatim any empirical solar wind speed formula attributed to Arge et al. (2003) or (2004) with its coefficients (e.g., 265, fs exponent, θb terms), and the sentence attributing it."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1709.01730",
  "prompt": "Quote verbatim the WSA speed formula(s) and coefficient values, with the sentence(s) attributing them to Arge et al. 2003/2004 or others; title/authors/journal."
}
